 29→
 30→/**
 31→ * Stop the session
 32→ */
 33→async function handleStop(e: Event) {
 34→  e.stopPropagation();
 35→  if (!session || stopping) return;
 36→
 37→  stopping = true;
 38→  stopError = null;
 39→
 40→  try {
 41→    await stopSession(session.id, 'Stopped by user');
 42→  } catch (err) {
 43→    stopError = err instanceof Error ? err.message : 'Failed to stop';
 44→    console.error('Failed to stop session:', err);
 45→  } finally {
 46→    stopping = false;
 47→  }
 48→}
