    69→  if (event.event === 'aggregated' && isMessageManagerEvent(event.data)) {
    70→    // Filter: only process events for our session
    71→    if (event.data.sessionId !== sessionInfo.id) return;
    72→
    73→    // Use the simplified semantic event handler
    74→    store.handleSemanticEvent(event.data);
    75→  }
    76→}
    77→
    78→/**
    79→ * Subscribe to session events via sessions:updates topic.
    80→ */
    81→function subscribeToSession() {
    82→  // Subscribe to the global sessions:updates topic
    83→  wsManager.subscribe([TOPIC_SESSIONS_UPDATES]);
    84→
    85→  // Handle events and filter for our session
    86→  const unsub = wsManager.onTopic(TOPIC_SESSIONS_UPDATES, handleSessionsUpdate);
    87→  cleanupFns.push(unsub);
    88→
    89→  // Cleanup subscription on unmount
    90→  cleanupFns.push(() => {
    91→    wsManager.unsubscribe([TOPIC_SESSIONS_UPDATES]);
    92→  });
    93→}
    94→
    95→/**
    96→ * Handle stop session
    97→ */
    98→async function handleStopSession() {
    99→  if (isStoppingSession) return;
   100→
   101→  isStoppingSession = true;
   102→  error = null;
   103→
   104→  try {
   105→    await stopSession(sessionInfo.id);
   106→    sessionInfo = { ...sessionInfo, status: 'completed' };
   107→  } catch (err) {
   108→    error = err instanceof Error ? err.message : String(err);
   109→  } finally {
   110→    isStoppingSession = false;
   111→  }
   112→}
   113→
   114→/**
   115→ * Handle message send from ChatInput
   116→ */
   117→async function handleSendMessage(content: string) {
   118→  try {
   119→    await wsManager.sendSessionMessage(sessionInfo.id, content);
   120→  } catch (err) {
   121→    error = err instanceof Error ? err.message : String(err);
   122→  }
   123→}
   124→
   125→/**
   126→ * Navigate back to sessions list
   127→ */
   128→function handleBack() {
   129→  goto('/sessions');
   130→}
   131→
   132→/**
   133→ * Handle WebSocket state changes to reset sequence tracking after reconnection.
   134→ * After reconnect, the Hub starts with seq=1 but the store may have a higher
   135→ * lastSeqProcessed, causing events to be silently dropped.
   136→ *
   137→ * @see kynetic-91ja - Bug: Hub UI stops rendering events after WebSocket reconnection
   138→ */
   139→function handleWsStateChange(newState: ConnectionState) {
   140→  // Detect reconnection: transitioning from 'reconnecting' to 'connected'
   141→  if (previousWsState === 'reconnecting' && newState === 'connected') {
   142→    if (store) {
   143→      store.resetSequenceTracking();
   144→    }
   145→  }
   146→  previousWsState = newState;
   147→}
   148→
   149→/**
   150→ * Load view mode preference from localStorage
   151→ */
   152→function loadViewModePreference() {
   153→  if (typeof window !== 'undefined') {
   154→    const saved = localStorage.getItem('session-view-mode');
   155→    if (saved === 'chat' || saved === 'split' || saved === 'spec') {
   156→      viewMode = saved;
   157→    }
   158→  }
   159→}
   160→
   161→/**
   162→ * Save view mode preference to localStorage
   163→ */
   164→function saveViewModePreference(mode: 'chat' | 'split' | 'spec') {
   165→  if (typeof window !== 'undefined') {
   166→    localStorage.setItem('session-view-mode', mode);
   167→  }
   168→  viewMode = mode;
   169→}
   170→
   171→onMount(() => {
   172→  loadViewModePreference();
   173→
   174→  // Listen for WebSocket state changes to handle reconnection
   175→  const unsubWsState = wsManager.onStateChange(handleWsStateChange);
   176→  cleanupFns.push(unsubWsState);
   177→
   178→  // Create streaming store and hydrate from REST data
   179→  // REST API returns AggregatedMessage[] format since Phase 2
   180→  const initialState = hydrateFromMessages(
   181→    data.session.id,
   182→    data.session.messages as AggregatedMessage[],
   183→    data.session.sessionMeta as SessionMeta | undefined,
   184→  );
   185→  store = createStreamingStore(data.session.id);
   186→  store.replaceState(initialState);
   187→
   188→  // Subscribe to WebSocket for real-time updates
   189→  subscribeToSession();
   190→});
   191→
   192→onDestroy(() => {
   193→  for (const cleanup of cleanupFns) {
   194→    cleanup();
   195→  }
   196→});
   197→
   198→// Derived: is session active
   199→const isActive = $derived(sessionInfo.status === 'active');
