/**
 * Hub API Types for the UI
 *
 * Types for REST API responses and WebSocket messages.
 * Based on packages/hub/src/http-api/types.ts and packages/hub/src/ui/types.ts
 */

// =============================================================================
// Task Types
// =============================================================================

export type TaskStatus =
  | 'pending'
  | 'ready'
  | 'assigned'
  | 'in_progress'
  | 'orphaned'
  | 'completed'
  | 'failed'
  | 'archived';

/**
 * VCS workspace state for task isolation.
 */
export type TaskWorkspaceState = 'active' | 'merging' | 'merged' | 'conflict' | 'abandoned';

/**
 * VCS workspace metadata attached to a task.
 * Provides visibility into JJ workspace state for crash recovery and UI display.
 */
export interface TaskVcsData {
  /** JJ workspace identifier (e.g., "main--task-42--01ARZ3NDEK") */
  workspace_id: string;
  /** Current JJ change ID */
  change_id?: string;
  /** Git commit hash (for colocated repos) */
  commit_hash?: string;
  /** Target branch for merge (e.g., "main") */
  target_branch: string;
  /** Current workspace state */
  state: TaskWorkspaceState;
  /** Files with conflicts (only when state = 'conflict') */
  conflicted_files?: string[];
}

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  /** 0-4 (0 = highest priority) */
  priority: number;
  /** Spoke ID if assigned */
  assigned_to?: string;
  /** Active session ID (if running) */
  current_session_id?: string;
  /** Past session IDs */
  session_history: string[];
  /** Feedback from the most recent rejection, if any */
  reject_feedback?: string;
  /** VCS workspace metadata (present if task has/had a workspace) */
  vcs?: TaskVcsData;
  /** Project this task belongs to (multi-project support) */
  project_id?: string;
  created_at: string;
  updated_at: string;
}

export interface TaskListResponse {
  tasks: Task[];
  total_count: number;
}

export interface TaskCreateRequest {
  title: string;
  description?: string;
  priority?: number;
}

export interface TaskUpdateRequest {
  title?: string;
  description?: string;
  priority?: number;
  status?: TaskStatus;
}

/**
 * Response wrapper for single task endpoints.
 * Most task endpoints return { task: Task } with optional additional fields.
 */
export interface TaskResponse {
  task: Task;
}

// =============================================================================
// Session Types
// =============================================================================

export type SessionStatus = 'active' | 'paused' | 'completed' | 'failed';
export type AgentType = 'task' | 'planner' | 'hub';
export type SessionMessageType =
  | 'user_message'
  | 'agent_message'
  | 'agent_thought'
  | 'tool_use'
  | 'tool_result'
  | 'interaction'
  | 'status';

export interface SessionContext {
  task_id?: string;
  spec_id?: string;
  spoke_id?: string;
  connected_session_id?: string;
}

export interface Session {
  id: string;
  agent_type: AgentType;
  status: SessionStatus;
  context?: SessionContext;
  /** Project this session belongs to (multi-project support) */
  project_id?: string;
  created_at: string;
  updated_at: string;
}

export interface SessionMessage {
  id: string;
  timestamp: string;
  type: SessionMessageType;
  data: unknown;
}

/**
 * SessionDetail - REST API response format.
 *
 * Note: Since Phase 2, the REST API returns AggregatedMessage[] format
 * instead of SessionMessage[]. Import from @kynetic/shared/aggregated-message
 * for the exact types.
 *
 * @see specs/STREAMING_MESSAGE_AGGREGATION.md Section 7
 */
export interface SessionDetail extends Session {
  /** Aggregated messages (AggregatedMessage[] from shared package) */
  messages: unknown[];
  /** Session metadata (plan, mode, commands) */
  sessionMeta?: {
    plan: { id: string; content: string; completed: boolean }[] | null;
    currentModeId: string | null;

